param(
  [string]$CursorApiKey = "",
  [string]$Environment = "github-pages",
  [string]$Service = "programa-ios-pages",
  [string]$Source = "https://github.com/LCV-Ideas-Software/programa-ios",
  [string]$DeployVersion = "1",
  [string]$Actor = "powershell-test",
  [ValidateSet("success", "failure", "cancelled")][string]$Outcome = "success",
  [int]$TimeoutSec = 20
)

$ErrorActionPreference = "Stop"
if ([string]::IsNullOrWhiteSpace($CursorApiKey)) {
  Write-Error "Defina CURSOR_API_KEY no ambiente ou passe -CursorApiKey."
  exit 1
}

Add-Type -AssemblyName System.Net.Http
$client = [System.Net.Http.HttpClient]::new()
$client.Timeout = [TimeSpan]::FromSeconds($TimeoutSec)

function Redact([string]$Text) {
  if ([string]::IsNullOrEmpty($Text)) { return "" }
  $hidden = $Text.Replace($CursorApiKey, "***")
  return [regex]::Replace($hidden, '("(?:accessToken|refreshToken|token)"\s*:\s*")[^"]*"', '$1***"')
}

function Invoke-RolloutsPost {
  param(
    [Parameter(Mandatory = $true)][string]$Name,
    [Parameter(Mandatory = $true)][string]$Url,
    [Parameter(Mandatory = $true)][hashtable]$Headers,
    [Parameter(Mandatory = $true)][string]$Body
  )
  $request = [System.Net.Http.HttpRequestMessage]::new([System.Net.Http.HttpMethod]::Post, $Url)
  foreach ($key in $Headers.Keys) {
    [void]$request.Headers.TryAddWithoutValidation($key, [string]$Headers[$key])
  }
  $content = [System.Net.Http.StringContent]::new($Body, [Text.Encoding]::UTF8, "application/json")
  $content.Headers.ContentType = [System.Net.Http.Headers.MediaTypeHeaderValue]::new("application/json")
  $request.Content = $content
  $watch = [Diagnostics.Stopwatch]::StartNew()
  try {
    $response = $client.SendAsync($request).GetAwaiter().GetResult()
    $raw = $response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
    $watch.Stop()
    return @{
      Name = $Name
      Url = $Url
      Status = [int]$response.StatusCode
      Milliseconds = $watch.ElapsedMilliseconds
      Bytes = [Text.Encoding]::UTF8.GetByteCount($raw)
      Body = $raw
      Error = $null
    }
  } catch {
    $watch.Stop()
    return @{
      Name = $Name
      Url = $Url
      Status = $null
      Milliseconds = $watch.ElapsedMilliseconds
      Bytes = 0
      Body = ""
      Error = $_.Exception.GetType().FullName + ": " + $_.Exception.Message
    }
  } finally {
    $request.Dispose()
  }
}

function Show-Call($Result) {
  Write-Output ("[{0}] {1}" -f $Result.Name, $Result.Url)
  if ($null -eq $Result.Status) {
    Write-Output ("  sem resposta em {0} ms, 0 bytes. {1}" -f $Result.Milliseconds, $Result.Error)
    return
  }
  Write-Output ("  HTTP {0} em {1} ms, {2} bytes" -f $Result.Status, $Result.Milliseconds, $Result.Bytes)
  $shown = Redact $Result.Body
  if (-not [string]::IsNullOrWhiteSpace($shown)) {
    Write-Output ("  corpo: {0}" -f $shown)
  }
}

$exchange = Invoke-RolloutsPost -Name "exchange" -Url "https://api2.cursor.sh/auth/exchange_user_api_key" -Headers @{ Authorization = "Bearer $CursorApiKey" } -Body "{}"
Show-Call $exchange
if ($null -eq $exchange.Status -or $exchange.Status -lt 200 -or $exchange.Status -ge 300) { exit 1 }
$token = ($exchange.Body | ConvertFrom-Json).accessToken
if ([string]::IsNullOrWhiteSpace($token)) {
  Write-Output "  a troca nao devolveu accessToken."
  exit 1
}

$api = @{ Authorization = "Bearer $token"; "Connect-Protocol-Version" = "1" }

$deploymentJson = '{"deployment":{"deploySourceUri":"' + $Source + '","environment":"environments/' + $Environment + '","service":"services/' + $Service + '","deployVersion":"' + $DeployVersion + '"},"event":{"started":{},"actor":"' + $Actor + '"}}'
$deploymentCall = Invoke-RolloutsPost -Name "CreateDeployment" -Url "https://api.cursor.com/factory.v1.DeploymentsService/CreateDeployment" -Headers $api -Body $deploymentJson
Show-Call $deploymentCall

$environmentJson = '{"environmentId":"' + $Environment + '","environment":{"displayName":"' + $Environment + '"}}'
$environmentCall = Invoke-RolloutsPost -Name "CreateEnvironment" -Url "https://api.cursor.com/factory.v1.DeploymentsService/CreateEnvironment" -Headers $api -Body $environmentJson
Show-Call $environmentCall

$serviceJson = '{"serviceId":"' + $Service + '","service":{"displayName":"' + $Service + '"}}'
$serviceCall = Invoke-RolloutsPost -Name "CreateService" -Url "https://api.cursor.com/factory.v1.DeploymentsService/CreateService" -Headers $api -Body $serviceJson
Show-Call $serviceCall

if ($null -eq $deploymentCall.Status -or $deploymentCall.Status -lt 200 -or $deploymentCall.Status -ge 300) { exit 1 }
$deploymentName = ($deploymentCall.Body | ConvertFrom-Json).deployment.name
if ([string]::IsNullOrWhiteSpace($deploymentName)) {
  Write-Output "  CreateDeployment nao devolveu deployment.name."
  exit 1
}

if ($Outcome -eq "success") {
  $finishJson = '{"name":"' + $deploymentName + '","event":{"completed":{"succeeded":{}},"actor":"' + $Actor + '"}}'
} elseif ($Outcome -eq "cancelled") {
  $finishJson = '{"name":"' + $deploymentName + '","event":{"aborted":{},"actor":"' + $Actor + '"}}'
} else {
  $finishJson = '{"name":"' + $deploymentName + '","event":{"completed":{"failed":{"message":"Deploy step failed"}},"actor":"' + $Actor + '"}}'
}
$finishCall = Invoke-RolloutsPost -Name "AppendDeploymentEvent" -Url "https://api.cursor.com/factory.v1.DeploymentsService/AppendDeploymentEvent" -Headers $api -Body $finishJson
Show-Call $finishCall
if ($null -eq $finishCall.Status -or $finishCall.Status -lt 200 -or $finishCall.Status -ge 300) { exit 1 }
Write-Output "deploy registrado."

