function Show-Report($repo, $runId) {
  Write-Output "=== JOBS $repo $runId ==="
  & gh api "repos/LCV-Ideas-Software/$repo/actions/runs/$runId/jobs" --jq ".jobs[] | {name,conclusion,steps:[.steps[] | select(.name|test(\"Rollouts\")) | {name,conclusion,number}]}"
