  & gh run view $runId --repo "LCV-Ideas-Software/$repo" --log | Select-String -Pattern 'rollouts-reporter\.sh|Rollouts reporter|##\[error\]|##\[warning\]' | ForEach-Object { $_.Line.Substring([Math]::Max(0, $_.Line.Length - 400)) }
}

