function Show-Alert($repo) {
  Write-Output "=== $repo ==="
  $json = & gh pr list --repo "LCV-Ideas-Software/$repo" --state all --limit 4 --json number
  if ($LASTEXITCODE -ne 0) { Write-Output "pr_list_exit=$LASTEXITCODE"; return }
  $prs = @($json | ConvertFrom-Json)
  foreach ($pr in $prs) {
    $raw = & gh api "repos/LCV-Ideas-Software/$repo/issues/$($pr.number)/comments"
    if ($LASTEXITCODE -ne 0) { Write-Output "comments_exit=$LASTEXITCODE pr=$($pr.number)"; continue }
    $comments = @($raw | ConvertFrom-Json)
    $bot = $comments | Where-Object { $_.user.login -eq 'cursor[bot]' } | Select-Object -Last 1
    if (-not $bot) { Write-Output "PR $($pr.number) sem comentario do Cursor"; continue }
    $setup = $bot.body -match 'finish-setup'
    $monitored = $bot.body -match 'Not monitored'
    Write-Output "PR $($pr.number) updated=$($bot.updated_at) setup=$setup not_monitored=$monitored"
  }
}

Show-Alert 'programa-ios'
