  @{ Source = 'https://github.com/LCV-Ideas-Software/oraculo-financeiro'; Env = 'github-pages'; Service = 'oraculo-financeiro-pages'; Sha = ( & gh api repos/LCV-Ideas-Software/oraculo-financeiro/commits/main --jq .sha ); Actor = 'goal-bootstrap' },
  @{ Source = 'https://github.com/LCV-Ideas-Software/mainsite-app'; Env = 'cloudflare-production'; Service = 'mainsite-motor'; Sha = '561245ea4ef53a9d51fd04572a612f8fc650a23b'; Actor = 'https://github.com/LCV-Ideas-Software/mainsite-app/actions/runs/43338812546/attempts/1' }
