  if ($dep.Status -lt 200 -or $dep.Status -ge 300) { continue }
  $name = ($dep.Body | ConvertFrom-Json).deployment.name
  $finBody = '{"name":"' + $name + '","event":{"completed":{"succeeded":{}},"actor":"' + $t.Actor + '"}}'
  [void](Invoke-Post 'AppendDeploymentEvent' 'https://api.cursor.com/factory.v1.DeploymentsService/AppendDeploymentEvent' $api $finBody)
