& gh pr list --repo LCV-Ideas-Software/github-operations --state open --search 'rollout OR deployment OR CURSOR_API_KEY' --limit 10 --json number,title,url,createdAt
& gh search prs --owner LCV-Ideas-Software 'rollouts reporter in:title' --state open --limit 20 --json repository,number,title,url 2>$null
