Write-Output '=== CURSOR INSTALLATION EVENTS/PERMS ==='
& gh api /orgs/LCV-Ideas-Software/installations --paginate --jq '.installations[] | select(.app_slug=="cursor") | {id,app_slug,repository_selection,permissions:.permissions,events:.events,html_url,updated_at}'

Write-Output '=== CURSOR_API_KEY present? ==='
if ([string]::IsNullOrWhiteSpace($env:CURSOR_API_KEY)) { Write-Output 'NO' } else { Write-Output ('YES len={0}' -f $env:CURSOR_API_KEY.Length) }

if ([string]::IsNullOrWhiteSpace($env:CURSOR_API_KEY)) { exit 2 }

Add-Type -AssemblyName System.Net.Http
$client = [System.Net.Http.HttpClient]::new()
$client.Timeout = [TimeSpan]::FromSeconds(30)
function Invoke-Post([string]$Name, [string]$Url, [hashtable]$Headers, [string]$Body) {
  $request = [System.Net.Http.HttpRequestMessage]::new([System.Net.Http.HttpMethod]::Post, $Url)
  foreach ($key in $Headers.Keys) { [void]$request.Headers.TryAddWithoutValidation($key, [string]$Headers[$key]) }
  $request.Content = [System.Net.Http.StringContent]::new($Body, [Text.Encoding]::UTF8, 'application/json')
  try {
    $response = $client.SendAsync($request).GetAwaiter().GetResult()
    $raw = $response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
    $safe = [regex]::Replace($raw, '("(?:accessToken|refreshToken|token)"\s*:\s*")[^"]*"', '$1***"')
    Write-Output ("[{0}] HTTP {1}" -f $Name, [int]$response.StatusCode)
    if ($safe.Length -gt 1200) { $safe = $safe.Substring(0,1200) + '...TRUNC' }
    Write-Output ("  body: {0}" -f $safe)
    return @{ Status = [int]$response.StatusCode; Body = $raw }
  } finally { $request.Dispose() }
}

$exchange = Invoke-Post 'exchange' 'https://api2.cursor.sh/auth/exchange_user_api_key' @{ Authorization = "Bearer $($env:CURSOR_API_KEY)" } '{}'
if ($exchange.Status -lt 200 -or $exchange.Status -ge 300) { exit 1 }
$token = ($exchange.Body | ConvertFrom-Json).accessToken
$api = @{ Authorization = "Bearer $token"; 'Connect-Protocol-Version' = '1' }

# Probe list/get RPCs that may exist on DeploymentsService
foreach ($rpc in @(
  'ListEnvironments',
  'ListServices',
  'ListDeployments',
  'GetDeployment',
  'ListDeploymentEvents'
)) {
  [void](Invoke-Post $rpc ("https://api.cursor.com/factory.v1.DeploymentsService/{0}" -f $rpc) $api '{}')
}

# Seed the two repos that still show finish-setup, using live SHAs from GitHub deployments
