function Invoke-CurlJson {
  param(
    [string]$Name,
    [string]$Url,
    [string[]]$Headers,
    [string]$Body
  )
  $tmp = Join-Path $env:TEMP ("rollouts-" + [guid]::NewGuid().ToString('N') + ".json")
  try {
    $args = @('-sS','--connect-timeout','15','--max-time','30','-o',$tmp,'-w','%{http_code}','-X','POST',$Url)
    foreach ($h in $Headers) { $args += @('-H', $h) }
    if ($null -ne $Body) {
      $args += @('-H','Content-Type: application/json','-d',$Body)
    }
    $code = & curl.exe @args
    $raw = if (Test-Path $tmp) { Get-Content -Raw -LiteralPath $tmp } else { '' }
    $safe = [regex]::Replace($raw, '("(?:accessToken|refreshToken|token)"\s*:\s*")[^"]*"', '$1***"')
    if ($safe.Length -gt 1500) { $safe = $safe.Substring(0,1500) + '...TRUNC' }
    Write-Output ("[{0}] HTTP {1}" -f $Name, $code)
    Write-Output ("  body: {0}" -f $safe)
    return @{ Status = [int]$code; Body = $raw }
  } catch {
    Write-Output ("[{0}] EXCEPTION {1}" -f $Name, $_.Exception.Message)
    return @{ Status = 0; Body = '' }
  } finally {
    Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
  }
}

