input.contents:
"""Remove Cursor Rollouts reporter wiring from one repository worktree.

The deploy steps stay. Only the reporter checkout, the start/finish reports,
the Play environment selector that exists only to feed the reporter, the
reporter env keys, the reporter script, and its dedicated test are removed.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

STEP_NAMES = {
    "Check out Rollouts reporter",
    "Report Rollouts deploy start",
    "Report Rollouts deploy result",
    "Select the Rollouts Play environment",
}
ENV_KEY = re.compile(
    r"^(\s*)(CHANGE_MONITOR_ENV|CHANGE_MONITOR_SERVICE|CHANGE_MONITOR_SOURCE|"
    r"CHANGE_MONITOR_ACTOR|DEPLOY_VERSION):"
)
STEP_START = re.compile(r"^(\s*)- name:\s*(.*?)\s*$")


def indent_of(line: str) -> int:
    return len(line) - len(line.lstrip(" "))


def remove_steps(text: str) -> str:
    lines = text.splitlines(keepends=True)
    kept: list[str] = []
    index = 0
    while index < len(lines):
        match = STEP_START.match(lines[index])
        name = match.group(2).strip().strip("'\"") if match else ""
        if match and name in STEP_NAMES:
            step_indent = len(match.group(1))
            index += 1
            while index < len(lines):
                current = lines[index]
                if current.strip() == "":
                    look = index + 1
                    while look < len(lines) and lines[look].strip() == "":
                        look += 1
                    if look >= len(lines):
                        index = look
                        break
                    next_indent = indent_of(lines[look])
                    if next_indent <= step_indent:
                        index = look
                        break
                    index = look
                    continue
                next_indent = indent_of(current)
                if next_indent <= step_indent and current.lstrip().startswith("- "):
                    break
                if next_indent < step_indent:
                    break
                index += 1
            continue
        kept.append(lines[index])
        index += 1
    return "".join(kept)


def remove_env_keys(text: str) -> str:
    lines = [line for line in text.splitlines(keepends=True) if not ENV_KEY.match(line)]
    kept: list[str] = []
    index = 0
    while index < len(lines):
        match = re.match(r"^(\s*)env:\s*$", lines[index])
        if match:
            env_indent = len(match.group(1))
            look = index + 1
            while look < len(lines) and lines[look].strip() == "":
                look += 1
            if look >= len(lines) or indent_of(lines[look]) <= env_indent:
                index = look
                continue
        kept.append(lines[index])
        index += 1
    return "".join(kept)


def strip_reporter_permission_comment(text: str) -> str:
    return text.replace(" # Read the Rollouts reporter script.", "")


def strip_test_listing(text: str) -> str:
    lines = []
    for line in text.splitlines(keepends=True):
        if "rollouts-reporter.test.mjs" in line:
            continue
        lines.append(line)
    return "".join(lines)


def update_institutional(text: str) -> str:
    text = text.replace(
        "The Rollouts reporter is a retained publication hook.\n",
        "",
    )
    text = text.replace('  ".github/scripts/rollouts-reporter.sh",\n', "")
    return text


def process_worktree(root: Path) -> list[str]:
    changed: list[str] = []
    for path in root.rglob("*"):
        if not path.is_file():
            continue
        relative = path.relative_to(root).as_posix()
        if relative.startswith(".git/") or "/temp/" in f"/{relative}/":
            continue
        if path.name == "rollouts-reporter.sh" or path.name == "rollouts-reporter.test.mjs":
            path.unlink()
            changed.append(f"deleted {relative}")
            continue
        if path.suffix not in {".yml", ".yaml", ".json", ".mjs"}:
            continue
        original = path.read_text(encoding="utf-8")
        updated = original
        if path.suffix in {".yml", ".yaml"}:
            updated = remove_steps(updated)
            updated = remove_env_keys(updated)
            updated = strip_reporter_permission_comment(updated)
            updated = strip_test_listing(updated)
        elif path.name == "package.json":
            updated = strip_test_listing(updated)
        elif path.name == "institutional-boundary.test.mjs":
            updated = update_institutional(updated)
        if updated != original:
            path.write_text(updated, encoding="utf-8", newline="\n")
            changed.append(f"edited {relative}")
    leftovers = []
    for path in root.rglob("*"):
        if not path.is_file():
            continue
        relative = path.relative_to(root).as_posix()
        if relative.startswith(".git/") or path.suffix not in {".yml", ".yaml", ".mjs", ".json"}:
            continue
        if "rollouts-reporter" in path.read_text(encoding="utf-8", errors="ignore"):
            leftovers.append(relative)
    if leftovers:
        changed.append("STILL MENTIONS rollouts-reporter: " + ", ".join(leftovers))
    return changed


def main() -> int:
    root = Path(sys.argv[1]).resolve()
    if not root.is_dir():
        print(f"missing {root}")
        return 1
    changes = process_worktree(root)
    print(f"=== {root.name} ===")
    if not changes:
        print("no changes")
    for line in changes:
        print(line)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
